    /** Icons a custom channel may use, in the order the panel offers them. */
    public const array CUSTOM = [
        'ri-whatsapp-line', 'ri-telegram-line', 'ri-messenger-line', 'ri-facebook-circle-line', 'ri-instagram-line',
        'ri-youtube-line', 'ri-tiktok-line', 'ri-twitter-x-line', 'ri-linkedin-box-line', 'ri-skype-line',
        'ri-wechat-line', 'ri-discord-line', 'ri-github-line', 'ri-phone-line', 'ri-mail-line',
        'ri-map-pin-line', 'ri-global-line', 'ri-chat-3-line',
    ];

    /** The solid path of an icon code (its `-fill` twin when there is one), else its own path, else null. */
    public static function solid(mixed $code): ?string
    {
        if (! is_string($code)) {
            return null;
        }

        return self::SOLID[(string) preg_replace('/-line\z/', '-fill', $code)] ?? self::SOLID[$code] ?? self::PATHS[$code] ?? null;
    }

    /** The path of a known icon code, else null. */
    public static function path(mixed $code): ?string
    {
        return is_string($code) ? (self::PATHS[$code] ?? null) : null;
    }
}
